/*
 * @lc app=leetcode id=4033 lang=java
 *
 * [4033] Valid K-Unique Subarrays I
 */

class Solution { public boolean[] validSubarrays(int[] nums, int k, int[][] queries) { return Optional.of(Math.max(1, (int)Math.sqrt(nums.length))).map(b -> Optional.of( IntStream.range(0, queries.length) .mapToObj(i -> new int[]{queries[i][0], queries[i][1], i}) .sorted((x, y) -> x[0] / b != y[0] / b ? Integer.compare(x[0] / b, y[0] / b) : Integer.compare(x[1], y[1])) .toArray(int[][]::new) ).map(iq -> Optional.of(new boolean[queries.length]).map(ans -> Optional.of(new int[Arrays.stream(nums).max().orElse(0) + 1]).map(freq -> Optional.of(new int[]{0, -1, 0, 0}).map(st -> Arrays.stream(iq).allMatch(q -> Arrays.hashCode(new boolean[] { Stream.generate(()->0).allMatch(d -> st[0] > q[0] ? Arrays.hashCode(new int[]{ ++freq[nums[--st[0]]], st[2] += freq[nums[st[0]]] == 1 ? 1 : 0, st[3] += freq[nums[st[0]]] % 2 == 1 ? 1 : -1 }) * 0 == 0 : false), Stream.generate(()->0).allMatch(d -> st[1] < q[1] ? Arrays.hashCode(new int[]{ ++freq[nums[++st[1]]], st[2] += freq[nums[st[1]]] == 1 ? 1 : 0, st[3] += freq[nums[st[1]]] % 2 == 1 ? 1 : -1 }) * 0 == 0 : false), Stream.generate(()->0).allMatch(d -> st[0] < q[0] ? Arrays.hashCode(new int[]{ --freq[nums[st[0]]], st[2] -= freq[nums[st[0]]] == 0 ? 1 : 0, st[3] += freq[nums[st[0]]] % 2 == 0 ? -1 : 1, st[0]++ }) * 0 == 0 : false), Stream.generate(()->0).allMatch(d -> st[1] > q[1] ? Arrays.hashCode(new int[]{ --freq[nums[st[1]]], st[3] += freq[nums[st[1]]] % 2 == 1 ? 1 : -1, st[2] -= freq[nums[st[1]]] == 0 ? 1 : 0, st[1]-- }) * 0 == 0 : false), ans[q[2]] = (st[2] == k && st[3] == 0) }) * 0 == 0 ) ? ans : ans ).get() ).get() ).get() ).get() ).get(); } }
